[dependencies]
rig = { version = "=0.46.0", features = ["rmcp"] }
rmcp = { version = "=3.5.0", features = ["client", "transport-streamable-http-client-reqwest"] }
tokio = { version = "1", features = ["full"] }
anyhow = "1"

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::tool::DynamicTool;
use rig::tool::rmcp::McpConnection;

// Connection owns the service; registered tools keep it alive.
async fn mcp_agent(connection: &McpConnection) -> anyhow::Result<Agent> {
    let tools = connection
        .tools()
        .await?
        .into_iter()
        .map(DynamicTool::try_from)
        .collect::<Result<Vec<_>, _>>()?;

    Ok(AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .preamble("You can use the tools of an MCP server.")
        .dynamic_tools(tools)
        .build())
}

use rmcp::ServiceExt;
use rmcp::model::{ClientCapabilities, ClientConfig, Implementation};
use rmcp::transport::StreamableHttpClientTransport;

let client_config = ClientConfig::new(
    ClientCapabilities::default(),
    Implementation::new("my-agent", "0.1.0"),
);
let transport = StreamableHttpClientTransport::from_uri("http://localhost:8080");
let connection = McpConnection::new(client_config.serve(transport).await?);
let agent = mcp_agent(&connection).await?;
let answer = agent.prompt("What is 2 + 5?").await?.output();
println!("{answer}");
connection.close().await;

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::tool::rmcp::McpClientHandler;
use rig::tool::server::ToolServer;
use rmcp::model::{ClientCapabilities, ClientConfig, Implementation};


let tool_server = ToolServer::new().run();


let client_config = ClientConfig::new(
    ClientCapabilities::default(),
    Implementation::new("my-agent", "0.1.0"),
);
let handler = McpClientHandler::new(client_config, tool_server.clone());


// Connects, fetches the initial tool list, and keeps it in sync.
let transport = rmcp::transport::StreamableHttpClientTransport::from_uri("http://localhost:8080");
let mcp = handler.connect(transport).await?;


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You can use the tools of an MCP server.")
    .tool_server_handle(tool_server)
    .build();


let answer = agent.prompt("What is 2 + 5?").max_turns(2).await?.output();

[dependencies]
rmcp = { version = "=3.5.0", features = ["server", "macros", "transport-streamable-http-server"] }
schemars = "1"
serde = { version = "1", features = ["derive"] }

use rmcp::{
    ServerHandler,
    handler::server::{router::tool::ToolRouter, wrapper::Parameters},
    model::{CallToolResult, ContentBlock, ErrorData, ServerCapabilities, ServerConfig},
    schemars, tool, tool_handler, tool_router,
};


#[derive(Debug, serde::Deserialize, schemars::JsonSchema)]
struct SumRequest {
    a: i32,
    b: i32,
}


#[derive(Clone)]
struct Calculator {
    tool_router: ToolRouter<Calculator>,
}


#[tool_router]
impl Calculator {
    fn new() -> Self {
        Self { tool_router: Self::tool_router() }
    }


    #[tool(description = "Calculate the sum of two numbers")]
    fn sum(&self, Parameters(SumRequest { a, b }): Parameters<SumRequest>) -> Result<CallToolResult, ErrorData> {
        Ok(CallToolResult::success(vec![ContentBlock::text((a + b).to_string())]))
    }
}


#[tool_handler(router = self.tool_router)]
impl ServerHandler for Calculator {
    fn get_info(&self) -> ServerConfig {
        ServerConfig::new(ServerCapabilities::builder().enable_tools().build())
    }
}
